// hid_prank_unicode.ino — ESP32-S3 (native USB HID)
// GPIO4: Win+R -> cmd -> color 2 -> dir /s -> F11 (весь текст через Alt+Numpad)
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

const int BTN = 4;

// Сырые HID-usages нумпада и прочих клавиш
const uint8_t KP0 = 0x62, KP1 = 0x59, KP2 = 0x5A, KP3 = 0x5B, KP4 = 0x5C;
const uint8_t KP5 = 0x5D, KP6 = 0x5E, KP7 = 0x5F, KP8 = 0x60, KP9 = 0x61;
const uint8_t KP_DIGITS[10] = {KP0, KP1, KP2, KP3, KP4, KP5, KP6, KP7, KP8, KP9};

const uint8_t HID_ALT     = 0xE2; // Left Alt (модификатор)
const uint8_t HID_GUI     = 0xE3; // Left Win
const uint8_t HID_R       = 0x15;
const uint8_t HID_ENTER   = 0x28;
const uint8_t HID_NUMLOCK = 0x53;
const uint8_t HID_F11     = 0x44;

struct Btn {
  uint8_t pin;
  bool lastReading = false, state = false;
  unsigned long lastChange = 0;
};
Btn btn{BTN};

bool checkPress(Btn &b) {
  bool reading = (digitalRead(b.pin) == LOW);
  if (reading != b.lastReading) { b.lastChange = millis(); b.lastReading = reading; }
  if (millis() - b.lastChange > 50 && reading != b.state) {
    b.state = reading;
    if (b.state) return true;
  }
  return false;
}

void tapKey(uint8_t usage) {
  Keyboard.pressRaw(usage);
  Keyboard.releaseRaw(usage);
  delay(20);
}

void tapNumLock() {
  Keyboard.pressRaw(HID_NUMLOCK);
  delay(40);
  Keyboard.releaseRaw(HID_NUMLOCK);
  delay(60);
}

// Символ через Alt+Numpad: ведущий ноль = ANSI-таблица, раскладка не важна
void typeAltChar(char c) {
  int code = (int)c;
  Keyboard.pressRaw(HID_ALT);
  delay(40);
  tapKey(KP_DIGITS[0]);                       // 0 -> ANSI
  String s = String(code);
  while (s.length() < 3) s = "0" + s;
  for (unsigned int i = 0; i < s.length(); i++) tapKey(KP_DIGITS[s[i] - '0']);
  delay(40);
  Keyboard.releaseRaw(HID_ALT);
  delay(40);
}

void typeAltString(const char* s) {
  for (unsigned int i = 0; i < strlen(s); i++) typeAltChar(s[i]);
}

void pressEnter() {
  tapKey(HID_ENTER);
  delay(200);
}

void runPrank() {
  tapNumLock();                                // включить нумпад

  // Win+R -> cmd
  Keyboard.pressRaw(HID_GUI);
  delay(60);
  Keyboard.pressRaw(HID_R);
  delay(60);
  Keyboard.releaseRaw(HID_R);
  delay(60);
  Keyboard.releaseRaw(HID_GUI);
  delay(500);
  typeAltString("cmd");
  pressEnter();
  delay(800);                                  // ждём окно консоли

  typeAltString("color 2");
  pressEnter();
  delay(200);

  typeAltString("dir /s");
  pressEnter();

  delay(300);
  tapKey(HID_F11);                             // на весь экран
}

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  Keyboard.begin();
  USB.begin();
}

void loop() {
  if (checkPress(btn)) runPrank();
}
